/**
 * Jinx Poppy Grower + Spy: rules tests.
 *
 * Wiki: https://wiki.bloodontheclocktower.com/Poppy_Grower
 * Wiki: https://wiki.bloodontheclocktower.com/Spy
 * (the wiki has no jinx page; each character's page lists the jinx under "Related Jinxes")
 *
 * Generated by `npm run scaffold:rules-tests`. Replace the `it.todo` with tests of the rule
 * the jinx imposes, where the engine can check it (for example a setup warning when only one
 * of the two may be in play). Paraphrase, never copy wiki prose.
 */
import { describe, expect, it } from 'vitest';
import { findJinx, jinxesAmong, type Script } from '#lib/core/data/index.ts';
import { committedGameData } from '#lib/core/testing/committed-data.ts';
import { castWith, run } from '#lib/core/model/fixtures.test-support.ts';
import type { CharacterLookup } from '#lib/core/model/characters.ts';
import type { Game } from '#lib/core/model/types.ts';
import { nightStepAlerts } from '#lib/core/rules/night-alerts.ts';
import { jinxRulesBetween } from '#lib/core/rules/jinxes.ts';

const scriptOf = (ids: string[]): Script => ({
	meta: { name: 'Jinxed' },
	entries: ids.map((id) => ({ kind: 'official' as const, id }))
});

describe('Poppy Grower + Spy jinx', () => {
	const data = committedGameData();
	const jinx = findJinx(data.jinxes, 'poppygrower', 'spy');

	it('is in jinxes.json between two official characters', () => {
		expect(data.byId.get('poppygrower')?.name).toBe('Poppy Grower');
		expect(data.byId.get('spy')?.name).toBe('Spy');
		expect(jinx).toBeDefined();
		expect(jinx?.reason).not.toBe('');
	});

	it('applies only when both characters are on the script', () => {
		expect(jinxesAmong(data.jinxes, ['poppygrower', 'spy'])).toContain(jinx);
		expect(jinxesAmong(data.jinxes, ['poppygrower'])).not.toContain(jinx);
		expect(jinxesAmong(data.jinxes, ['spy'])).not.toContain(jinx);
	});

	// Both pages' Related Jinxes: while the Poppy Grower has its ability, the Spy does
	// not see the Grimoire. Its step says so (the Storyteller can still show it).
	describe("the Spy doesn't see the Grimoire while the Poppy Grower has its ability", () => {
		const cast = castWith({
			script: scriptOf(['spy', 'poppygrower', 'imp', 'chef', 'empath', 'poisoner'])
		});
		const grimoire = (game: Game, ctx: { characters: CharacterLookup }) =>
			nightStepAlerts(game, 'spy', ctx.characters).filter((a) => a.kind === 'no-grimoire');

		it("is data in the Spy's rules", () => {
			expect(jinxRulesBetween('spy', 'poppygrower')).toEqual({ noGrimoire: true });
		});

		it('says so at its step while the Poppy Grower lives', () => {
			const { session, ctx, seats } = cast(['spy', 'poppygrower', 'imp', 'chef', 'empath']);
			expect(grimoire(session.game, ctx).map((a) => [a.seatId, a.source, a.works])).toEqual([
				[seats[0], { characterId: 'poppygrower', seatId: seats[1] }, true]
			]);
			const dead = run(session, ctx, { type: 'SetDead', seatId: seats[1], dead: true });
			expect(grimoire(dead.game, ctx)).toEqual([]);
		});

		it('marks it not working while the Poppy Grower is poisoned', () => {
			const { session, ctx, seats } = cast(['spy', 'poppygrower', 'imp', 'chef', 'poisoner']);
			const { game } = run(session, ctx, {
				type: 'AddReminder',
				seatId: seats[1],
				reminder: { characterId: 'poisoner', label: 'Poisoned' }
			});
			expect(grimoire(game, ctx).map((a) => a.works)).toEqual([false]);
		});
	});
});
